389	    comment: DecoratedComment<JsLanguage>,
390	) -> CommentPlacement<JsLanguage> {
391	    match comment.enclosing_node().kind() {
392	        JsSyntaxKind::JS_LABELED_STATEMENT => {
393	            CommentPlacement::leading(comment.enclosing_node().clone(), comment)
394	        }
395	        _ => CommentPlacement::Default(comment),
396	    }
