/// Keeps trailing line comments on a `case` clause on the same line as the
/// `case` keyword when the clause's body is a block statement that hugs the
/// clause.
///
/// When a `case` clause's only statement is a block statement, the block hugs
/// the clause and its opening brace is printed on the same line:
///
/// ```javascript
/// switch (key) {
///   case a: // comment a
///   case b: { // comment b
///     doStuff();
///   }
/// }
/// ```
///
/// Before the block hugs the clause, `// comment b` is a trailing comment of
/// the clause's test. After the block hugs, the comment sits right after the
/// opening brace and would otherwise become a leading comment of the first
/// statement inside the block, moving it into the block on the next format
/// pass. Re-attaching it as a trailing comment of the clause's test preserves
/// its placement and makes formatting idempotent.
fn handle_switch_case_clause_comment(
    comment: DecoratedComment<JsLanguage>,
) -> CommentPlacement<JsLanguage> {
    // Only a line comment directly following the opening brace (no preceding
    // node inside the block) is affected.
    if !comment.kind().is_line() || comment.preceding_node().is_some() {
        return CommentPlacement::Default(comment);
    }

    let Some(block) = JsBlockStatement::cast_ref(comment.enclosing_node()) else {
        return CommentPlacement::Default(comment);
    };

    // The block statement must be the body of a `case` clause. Its direct parent
    // is the clause's statement list, whose parent is the clause itself.
    let Some(case_clause) = block
        .syntax()
        .parent()
        .and_then(|list| list.parent())
        .and_then(JsCaseClause::cast)
    else {
        return CommentPlacement::Default(comment);
    };

    // The comment stays on the `case` line only when the block hugs the clause,
    // i.e. it is the single non-empty statement of the clause's body. Otherwise
    // the opening brace is printed on its own line and the comment belongs to
    // the block.
    let consequent = case_clause.consequent();
    let is_single_block_statement = matches!(
        consequent.iter().next(),
        Some(AnyJsStatement::JsBlockStatement(_))
    ) && consequent
        .iter()
        .filter(|statement| !matches!(statement, AnyJsStatement::JsEmptyStatement(_)))
        .count()
        == 1;

    if !is_single_block_statement {
        return CommentPlacement::Default(comment);
    }

    match case_clause.test() {
        Ok(test) => CommentPlacement::trailing(test.into_syntax(), comment),
        Err(_) => CommentPlacement::Default(comment),
    }
}

